;(()=>{// MX Online Now visible second-by-second (same formula as /api/visitors).
const el=document.getElementById('visitorsNow');
if(!el)return;
const anchor=Date.UTC(2026,9,26,18,23,48);
const draw=()=>{
  const sec=Math.max(0,Math.floor((Date.now()-anchor)/1000));
  const phase=sec%24000;
  el.textContent=(15000+(phase<=12000?phase:24000-phase)).toLocaleString('en-US');
};
draw();
setInterval(draw,1000);
})();
